        StringParam(id='config_name', long_name='none', transmittable=False, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p></body></html>', format='qrich'), c_define='', value='balance_config', max_len=0),
        InfoParam(id='hw_name', long_name='Balance ex Settings', transmittable=False, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">This is the VESC Logging and Communication Module.</p></body></html>', format='qrich'), c_define=''),
        BoolParam(id='balance_enabled', long_name='Balancing enabled', transmittable=True, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Enable/disable balancing. Turn it off to experiment with base motor settings without the balance interfering.</p></body></html>', format='qrich'), c_define='APPCONF_BALANCE_ENABLED', value=False),
        DoubleParam(id='error_linear_limit', long_name='Error response linear limit', transmittable=True, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">PID error is calculated using this function (<a href="https://www.desmos.com/calculator/d0ergbkhie"><span style=" text-decoration: underline; color:#9696ff;">desmos</span></a>):</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">y = x { 0&lt;x&lt;d }</p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">y = k ln( (x-d)/k +1 ) + d, { x &gt;= d }</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Where <span style=" font-weight:600;">y</span> is the <span style=" font-weight:600;">error</span>; <span style=" font-weight:600;">x</span> is the pitch in degrees.</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">It starts linear up to a limit and then descreses logarithmically with a specific slope.</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">This parameter controls <span style=" font-weight:600;">d</span></p></body></html>', format='qrich'), c_define='APPCONF_ERROR_LINEAR_LIMIT', value=90.0, min_double=0.0, max_double=90.0, step_double=0.1, editor_decimals=1, editor_scale=1.0, edit_as_percentage=False, show_display=False, vtx_double_scale=1, suffix='', vtx=9),
        DoubleParam(id='error_ln_slope', long_name='Error logarithm slope', transmittable=True, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">PID error is calculated using this function (<a href="https://www.desmos.com/calculator/d0ergbkhie"><span style=" text-decoration: underline; color:#9696ff;">desmos</span></a>):</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">y = x { 0&lt;x&lt;d }</p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">y = k ln( (x-d)/k +1 ) + d, { x &gt;= d }</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Where <span style=" font-weight:600;">y</span> is the <span style=" font-weight:600;">error</span>; <span style=" font-weight:600;">x</span> is the pitch in degrees.</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">It starts linear up to a limit and then descreses logarithmically with a specific slope.</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">This parameter controls <span style=" font-weight:600;">k</span></p></body></html>', format='qrich'), c_define='APPCONF_ERROR_LN_SLOPE', value=0.1, min_double=0.1, max_double=50.0, step_double=0.1, editor_decimals=1, editor_scale=1.0, edit_as_percentage=False, show_display=False, vtx_double_scale=1, suffix='', vtx=9),
        EnumParam(id='pid_mode', long_name='PID Mode', transmittable=True, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">PID loop mode, Angle or Cascadeing Angle Rate.</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Alternative (alt) mode changes the way proportional component is calculated. In the original cascade mode the rate P parameter directly affects the first PID value. It means that every adjustment to rate P requires corresponding adjustment to the angle P to keed the same &quot;pedal stiffness&quot; at constant angle. In alternative mode it only affects the error (0 - gyro_y) of the second PID which allows tuning the second part without touching the behavior of the first one.</p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Additionally alt mode adds the deadzone, making the regulator engange only after specific gyro_y threshold. </p></body></html>', format='qrich'), c_define='APPCONF_BALANCE_PID_MODE', value=1, enum_names=['BALANCE_PID_MODE_ANGLE', 'BALANCE_PID_MODE_ANGLE_RATE_CASCADE', 'BALANCE_PID_MODE_ANGLE_RATE_CASCADE_ALT']),
