        DoubleParam(id='kexp', long_name='Angle exponential', transmittable=True, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Exponential component defined as <span style=" font-weight:600;">e^(kx) - 1</span></p>\n<p style="-qt-paragraph-type:empty; margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; font-weight:600;"><br /></p>\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">This parameter controls the &quot;steepness&quot; of the exponent, <span style=" font-weight:600;">k </span></p></body></html>', format='qrich'), c_define='APPCONF_BALANCE_KEXP', value=0.0, min_double=0.0, max_double=20.0, step_double=0.1, editor_decimals=2, editor_scale=1.0, edit_as_percentage=False, show_display=False, vtx_double_scale=1, suffix='', vtx=9),
