        DoubleParam(id='pid2_deadzone', long_name='Rate PID deadzone', transmittable=True, description=Description(text='<!DOCTYPE HTML PUBLIC "-//W3C//DTD HTML 4.0//EN" "http://www.w3.org/TR/REC-html40/strict.dtd">\n<html><head><meta name="qrichtext" content="1" /><style type="text/css">\np, li { white-space: pre-wrap; }\n</style></head><body style=" font-family:\'Roboto\'; ; font-weight:400; font-style:normal;">\n<p style=" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;">Rate PID deadzone. Shifts the regulator error (0 - gyro_y) by this value (in °/s) delaying its effect.</p></body></html>', format='qrich'), c_define='APPCONF_BALANCE_PID2_DEADZONE', value=0.0, min_double=0.0, max_double=10.0, step_double=0.01, editor_decimals=2, editor_scale=1.0, edit_as_percentage=False, show_display=False, vtx_double_scale=1000, suffix='', vtx=9),
